// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Deployed at: 0xb8C793ea9201b0875BEc927585Ca101D8A142E7F

import "@openzeppelin/contracts/access/Ownable.sol";
import "./SwapStepsConfigStore.sol";

/* =========================================================
 * External DEX interfaces — quoting only
 * ========================================================= */

/// @dev Uniswap V2 / SushiSwap V2 / Camelot V2 routers all expose this.
interface IUniswapV2RouterQuote {
    function getAmountsOut(
        uint256 amountIn,
        address[] calldata path
    ) external view returns (uint256[] memory amounts);

    function getAmountsIn(
        uint256 amountOut,
        address[] calldata path
    ) external view returns (uint256[] memory amounts);
}

/// @dev Uniswap V3 / Sushi V3 pool — direct swap simulation for quoting.
///      Same signature as Algebra pools.
interface IV3PoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/// @dev Algebra (Camelot V3) pool — same swap signature, different callback name.
interface IAlgebraPoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroToOne,
        int256 amountSpecified,
        uint160 limitSqrtPrice,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/// @dev Uniswap V4 Quoter — deployed on Arbitrum at 0x3972C00f7Ed4885e145823eb7c655375D6f1e2a4
interface IUniswapV4Quoter {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24  fee;
        int24   tickSpacing;
        address hooks;
    }

    struct QuoteExactSingleParams {
        PoolKey poolKey;
        bool    zeroForOne;
        uint128 exactAmount;
        bytes   hookData;
    }

    function quoteExactInputSingle(
        QuoteExactSingleParams memory params
    ) external returns (uint256 amountOut, uint256 gasEstimate);

    function quoteExactOutputSingle(
        QuoteExactSingleParams memory params
    ) external returns (uint256 amountIn, uint256 gasEstimate);
}

/* =========================================================
 * ArbQuoter — read-only quoting via DEX Router / direct pool simulation
 *
 * V2 / CamelotV2 (kind=0,2): router.getAmountsOut
 * V3            (kind=1):     direct pool.swap + uniswapV3SwapCallback revert
 * Algebra       (kind=3):     direct pool.swap + algebraSwapCallback revert
 * ========================================================= */
contract ArbQuoter is Ownable {

    // =========================================================
    // State
    // =========================================================

    SwapStepsConfigStore public configStore;
    address public v4Quoter;  // Uniswap V4 Quoter address

    // =========================================================
    // Errors
    // =========================================================

    error ZERO_ADDRESS();
    error UNKNOWN_KIND(uint8 kind);
    error NO_STEPS();

    /// @dev Thrown inside swap callbacks to carry the quote result back via revert.
    ///      For ExactIn:  amountIn = input spent, amountOut = output received
    ///      For ExactOut: amountIn = input required, amountOut = exact output requested
    error QuoteCallbackResult(uint256 amountIn, uint256 amountOut);

    // =========================================================
    // Constants — Algebra sqrt price limits (same as AlgebraSwapLib)
    // =========================================================

    uint160 private constant ALG_MIN_SQRT_RATIO = 4295128739;
    uint160 private constant ALG_MAX_SQRT_RATIO =
        1461446703485210103287273052203988822378723970342;

    // =========================================================
    // Structs — results
    // =========================================================

    struct QuoteResult {
        uint256 index;
        uint256 amountOut;
        bool    success;
    }

    struct QuoteBatchResult {
        QuoteResult[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @dev Price impact result for ExactIn quotes.
    /// - amountOut: output for amountIn
    /// - referenceAmountOut: output for referenceAmountIn (usually 100x smaller)
    /// - outPerInX18/referenceOutPerInX18: normalized prices in tokenOut per tokenIn, scaled by 1e18
    /// - priceImpactPpm: price impact in ppm (1e6 = 100%)
    /// - sellAmountOut: reverse ExactOut cost in tokenOut to buy back amountIn tokenIn
    /// - profit: int256(amountOut) - int256(sellAmountOut), both in tokenOut
    struct ImpactQuoteResult {
        uint256 amountOut;
        uint256 referenceAmountOut;
        uint256 outPerInX18;
        uint256 referenceOutPerInX18;
        uint256 priceImpactPpm;
        uint256 sellAmountOut;
        int256  profit;
        bool canTradeAmountIn; // true if target amountIn quote succeeded and produced non-zero output
        bool success;
    }

    struct ImpactQuoteBatchItem {
        uint256 index;
        uint256 amountOut;
        uint256 referenceAmountOut;
        uint256 outPerInX18;
        uint256 referenceOutPerInX18;
        uint256 priceImpactPpm;
        uint256 sellAmountOut;
        int256  profit;
        bool canTradeAmountIn;
        bool success;
    }

    struct ImpactQuoteBatchResult {
        ImpactQuoteBatchItem[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    struct RoundTripResult {
        uint256 index;
        uint256 buyAmountOut;   // ExactIn:  amountIn tokenIn → buyAmountOut tokenOut
        uint256 sellAmountOut;  // ExactOut: sellAmountOut tokenOut → amountIn tokenIn (how much tokenOut needed to get amountIn back)
        int256  profit;         // int256(buyAmountOut) - int256(sellAmountOut), both in tokenOut. Positive = profitable.
        bool    success;
    }

    struct RoundTripBatchResult {
        RoundTripResult[] trips;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Constructor
    // =========================================================

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================================================
    // Setters (onlyOwner)
    // =========================================================

    function setConfigStore(address _configStore) external onlyOwner {
        if (_configStore == address(0)) revert ZERO_ADDRESS();
        configStore = SwapStepsConfigStore(_configStore);
    }

    function setV4Quoter(address _v4Quoter) external onlyOwner {
        if (_v4Quoter == address(0)) revert ZERO_ADDRESS();
        v4Quoter = _v4Quoter;
    }

    // =========================================================
    // Swap callbacks — always revert with the quote result
    // =========================================================

    /// @dev Called by Uniswap V3 / Sushi V3 pools during swap simulation.
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Called by Algebra (Camelot V3) pools during swap simulation.
    function algebraSwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Shared callback logic: decode direction, extract amounts, revert.
    ///      For zeroForOne: token0 is input, token1 is output.
    ///      Positive delta = amount to pay (input), negative delta = amount received (output).
    function _revertWithQuote(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata /* data */
    ) internal pure {
        // amountIn  = the positive delta (what pool asks us to pay)
        // amountOut = the abs of negative delta (what pool gives us)
        uint256 amtIn;
        uint256 amtOut;

        if (amount0Delta > 0) {
            amtIn  = uint256(amount0Delta);
            amtOut = amount1Delta < 0 ? uint256(-amount1Delta) : 0;
        } else {
            amtIn  = amount1Delta > 0 ? uint256(amount1Delta) : 0;
            amtOut = uint256(-amount0Delta);
        }

        revert QuoteCallbackResult(amtIn, amtOut);
    }

    // =========================================================
    // Method 1: quoteExactIn — single step
    // =========================================================

    /// @notice Get a quote for a single swap step.
    function quoteExactIn(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (uint256 amountOut, bool success) {
        return _quoteExactInSafe(step, amountIn);
    }

    /// @notice Get quote and price impact for a single step.
    /// @param amountIn Target trade size.
    /// @param referenceAmountIn Reference (smaller) trade size, e.g. amountIn/100.
    function quoteExactInWithImpact(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) external returns (ImpactQuoteResult memory result) {
        return _quoteExactInWithImpact(step, amountIn, referenceAmountIn);
    }

    /// @notice Get quote and price impact with auto reference size (amountIn / 100).
    function quoteExactInWithImpact(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (ImpactQuoteResult memory result) {
        uint256 referenceAmountIn = amountIn / 100;
        if (referenceAmountIn == 0) referenceAmountIn = 1;
        return _quoteExactInWithImpact(step, amountIn, referenceAmountIn);
    }

    // =========================================================
    // Method 2: quoteExactInBatch — multiple steps
    // =========================================================

    /// @notice Quote all steps directly (calldata).
    function quoteExactInBatch(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) external returns (QuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        result.quotes = _quoteExactInBatchInternal(steps, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Quote all steps by store key.
    function quoteExactInBatchByKey(
        bytes32 key,
        uint256 amountIn
    ) external returns (QuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.quotes = _quoteExactInBatchMem(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Quote all steps with price impact directly (calldata).
    function quoteExactInBatchWithImpact(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) external returns (ImpactQuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        result.quotes = _quoteExactInBatchWithImpactCalldata(steps, amountIn, referenceAmountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Quote all steps with price impact by store key.
    function quoteExactInBatchWithImpactByKey(
        bytes32 key,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) external returns (ImpactQuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.quotes = _quoteExactInBatchWithImpactMem(raw, amountIn, referenceAmountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Method 3: quoteRoundTrip — single step (approximation)
    // =========================================================

    /// @notice Quote forward + reverse for a single step.
    ///         Approximation: ExactIn forward, then ExactIn reverse with buyAmountOut.
    function quoteRoundTrip(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (RoundTripResult memory) {
        return _quoteRoundTripInternal(step, amountIn, 0);
    }

    // =========================================================
    // Method 4: quoteRoundTripBatch — multiple steps
    // =========================================================

    /// @notice Round-trip quote all steps directly (calldata).
    function quoteRoundTripBatch(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) external returns (RoundTripBatchResult memory result) {
        uint256 gasStart = gasleft();
        result.trips = _quoteRoundTripBatchCalldata(steps, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Round-trip quote all steps by store key.
    function quoteRoundTripBatchByKey(
        bytes32 key,
        uint256 amountIn
    ) external returns (RoundTripBatchResult memory result) {
        uint256 gasStart = gasleft();
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.trips = _quoteRoundTripBatchMem(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Internal — core quoting logic
    // =========================================================

    /// @dev Quote a single step. Reverts on unknown kind.
    function _quoteExactIn(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        uint8 kind = step.kind;

        // V2_EXACT_IN (kind=0) or CAMELOT_V2_EXACT_IN (kind=2)
        if (kind == 0 || kind == 2) {
            address[] memory path = step.path;
            if (path.length < 2) {
                path = new address[](2);
                path[0] = step.tokenIn;
                path[1] = step.tokenOut;
            }
            uint256[] memory amounts = IUniswapV2RouterQuote(step.router)
                .getAmountsOut(amountIn, path);
            return amounts[amounts.length - 1];
        }

        // V3_POOL_EXACT_IN (kind=1) — direct pool swap simulation
        if (kind == 1) {
            return _quoteV3ExactIn(step.pool, step.tokenIn, amountIn);
        }

        // ALGEBRA_POOL_EXACT_IN (kind=3) — direct pool swap simulation
        if (kind == 3) {
            return _quoteAlgebraExactIn(step.pool, step.tokenIn, amountIn);
        }

        // V4_POOL_EXACT_IN (kind=4) — via external Uniswap V4 Quoter
        if (kind == 4) {
            return _quoteV4ExactIn(step, amountIn);
        }

        revert UNKNOWN_KIND(kind);
    }

    /// @dev Quote Uniswap V3 / Sushi V3 pool via swap simulation + callback-revert.
    ///      Pool calls uniswapV3SwapCallback → we revert with QuoteCallbackResult.
    function _quoteV3ExactIn(
        address pool,
        address tokenIn,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        address t0 = IV3PoolQuote(pool).token0();
        bool zeroForOne = (tokenIn == t0);

        uint160 limit = zeroForOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroForOne);

        try IV3PoolQuote(pool).swap(
            address(this),
            zeroForOne,
            int256(amountIn),       // positive = ExactIn
            limit,
            cbData
        ) {
            revert("V3_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            (, amountOut) = _decodeQuoteRevert(reason);
        }
    }

    /// @dev Quote V3 ExactOut: how much tokenIn is needed to get exactly amountOut tokenOut.
    function _quoteV3ExactOut(
        address pool,
        address tokenIn,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        address t0 = IV3PoolQuote(pool).token0();
        bool zeroForOne = (tokenIn == t0);

        uint160 limit = zeroForOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroForOne);

        try IV3PoolQuote(pool).swap(
            address(this),
            zeroForOne,
            -int256(amountOut),     // negative = ExactOut
            limit,
            cbData
        ) {
            revert("V3_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            (amountIn,) = _decodeQuoteRevert(reason);
        }
    }

    /// @dev Quote Algebra (Camelot V3) pool via swap simulation + callback-revert.
    function _quoteAlgebraExactIn(
        address pool,
        address tokenIn,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        address t0 = IAlgebraPoolQuote(pool).token0();
        bool zeroToOne = (tokenIn == t0);

        uint160 limit = zeroToOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroToOne);

        try IAlgebraPoolQuote(pool).swap(
            address(this),
            zeroToOne,
            int256(amountIn),       // positive = ExactIn
            limit,
            cbData
        ) {
            revert("ALGEBRA_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            (, amountOut) = _decodeQuoteRevert(reason);
        }
    }

    /// @dev Quote Algebra ExactOut: how much tokenIn is needed to get exactly amountOut tokenOut.
    function _quoteAlgebraExactOut(
        address pool,
        address tokenIn,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        address t0 = IAlgebraPoolQuote(pool).token0();
        bool zeroToOne = (tokenIn == t0);

        uint160 limit = zeroToOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroToOne);

        try IAlgebraPoolQuote(pool).swap(
            address(this),
            zeroToOne,
            -int256(amountOut),     // negative = ExactOut
            limit,
            cbData
        ) {
            revert("ALGEBRA_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            (amountIn,) = _decodeQuoteRevert(reason);
        }
    }

    // =========================================================
    // Internal — V4 quoting (via external Uniswap V4 Quoter)
    // =========================================================

    error V4_QUOTER_NOT_SET();

    /// @dev Build a V4 PoolKey from SwapStep V4 fields.
    ///      currency0 must be < currency1 (sorted order).
    function _buildV4PoolKey(
        SwapStepsConfigStore.SwapStep memory step
    ) internal pure returns (IUniswapV4Quoter.PoolKey memory key) {
        address c0;
        address c1;
        if (step.tokenIn < step.tokenOut) {
            c0 = step.tokenIn;
            c1 = step.tokenOut;
        } else {
            c0 = step.tokenOut;
            c1 = step.tokenIn;
        }
        key = IUniswapV4Quoter.PoolKey({
            currency0:   c0,
            currency1:   c1,
            fee:         step.v4Fee,
            tickSpacing: step.v4TickSpacing,
            hooks:       step.v4Hooks
        });
    }

    /// @dev Quote V4 ExactIn via external Uniswap V4 Quoter.
    function _quoteV4ExactIn(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        if (v4Quoter == address(0)) revert V4_QUOTER_NOT_SET();

        IUniswapV4Quoter.PoolKey memory poolKey = _buildV4PoolKey(step);
        bool zeroForOne = (step.tokenIn < step.tokenOut);

        IUniswapV4Quoter.QuoteExactSingleParams memory params =
            IUniswapV4Quoter.QuoteExactSingleParams({
                poolKey:    poolKey,
                zeroForOne: zeroForOne,
                exactAmount: uint128(amountIn),
                hookData:   ""
            });

        (amountOut,) = IUniswapV4Quoter(v4Quoter).quoteExactInputSingle(params);
    }

    /// @dev Quote V4 ExactOut via external Uniswap V4 Quoter.
    function _quoteV4ExactOut(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        if (v4Quoter == address(0)) revert V4_QUOTER_NOT_SET();

        // For ExactOut, we invert: we want to know how much tokenIn to pay to get amountOut tokenOut
        IUniswapV4Quoter.PoolKey memory poolKey = _buildV4PoolKey(step);
        bool zeroForOne = (step.tokenIn < step.tokenOut);

        IUniswapV4Quoter.QuoteExactSingleParams memory params =
            IUniswapV4Quoter.QuoteExactSingleParams({
                poolKey:    poolKey,
                zeroForOne: zeroForOne,
                exactAmount: uint128(amountOut),
                hookData:   ""
            });

        (amountIn,) = IUniswapV4Quoter(v4Quoter).quoteExactOutputSingle(params);
    }

    /// @dev Decode QuoteCallbackResult(uint256, uint256) from revert data.
    function _decodeQuoteRevert(
        bytes memory reason
    ) internal pure returns (uint256 amtIn, uint256 amtOut) {
        bytes4 expected = QuoteCallbackResult.selector;
        if (reason.length >= 68) {
            bytes4 sel;
            assembly { sel := mload(add(reason, 32)) }
            if (sel == expected) {
                assembly {
                    amtIn  := mload(add(reason, 36))
                    amtOut := mload(add(reason, 68))
                }
                return (amtIn, amtOut);
            }
        }
        // Unknown revert — propagate
        assembly { revert(add(reason, 32), mload(reason)) }
    }

    /// @dev Safe wrapper: returns (amountOut, success). Does not revert on failure.
    function _quoteExactInSafe(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut, bool success) {
        try this._quoteExactInExternal(step, amountIn) returns (uint256 out) {
            return (out, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev Quote target/reference sizes and derive price impact.
    ///      priceImpactPpm = ((pRef - pTarget) / pRef) * 1e6, where p = outPerIn.
    function _quoteExactInWithImpact(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteResult memory r) {
        if (amountIn == 0 || referenceAmountIn == 0) {
            r.success = false;
            return r;
        }

        (uint256 outTarget, bool okTarget) = _quoteExactInSafe(step, amountIn);
        (uint256 outRef, bool okRef) = _quoteExactInSafe(step, referenceAmountIn);

        r.amountOut = outTarget;
        r.referenceAmountOut = outRef;
        r.canTradeAmountIn = okTarget && outTarget > 0;

        if (r.canTradeAmountIn) {
            SwapStepsConfigStore.SwapStep memory inv = _invertStep(step);
            (uint256 sellCost, bool sellOk) = _quoteExactOutSafe(inv, amountIn);
            if (sellOk) {
                r.sellAmountOut = sellCost;
                r.profit = outTarget >= sellCost
                    ? int256(outTarget - sellCost)
                    : -int256(sellCost - outTarget);
            }
        }

        if (!okTarget || !okRef || outTarget == 0 || outRef == 0) {
            r.success = false;
            return r;
        }

        uint256 pTargetX18 = (outTarget * 1e18) / amountIn;
        uint256 pRefX18 = (outRef * 1e18) / referenceAmountIn;

        r.outPerInX18 = pTargetX18;
        r.referenceOutPerInX18 = pRefX18;

        if (pRefX18 == 0 || pTargetX18 >= pRefX18) {
            r.priceImpactPpm = 0;
        } else {
            r.priceImpactPpm = ((pRefX18 - pTargetX18) * 1_000_000) / pRefX18;
        }

        r.success = true;
    }

    /// @dev External wrapper needed for try/catch on internal memory-param function.
    ///      Must only be called by this contract itself.
    function _quoteExactInExternal(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (uint256) {
        require(msg.sender == address(this), "SELF_ONLY");
        return _quoteExactIn(step, amountIn);
    }

    // =========================================================
    // Internal — ExactOut quoting
    // =========================================================

    /// @dev Quote ExactOut: how much tokenIn is needed to receive exactly amountOut tokenOut.
    function _quoteExactOut(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        uint8 kind = step.kind;

        // V2 / Camelot V2: router.getAmountsIn
        if (kind == 0 || kind == 2) {
            address[] memory path = step.path;
            if (path.length < 2) {
                path = new address[](2);
                path[0] = step.tokenIn;
                path[1] = step.tokenOut;
            }
            uint256[] memory amounts = IUniswapV2RouterQuote(step.router)
                .getAmountsIn(amountOut, path);
            return amounts[0];
        }

        // V3: ExactOut via pool.swap with negative amountSpecified
        if (kind == 1) {
            return _quoteV3ExactOut(step.pool, step.tokenIn, amountOut);
        }

        // Algebra: ExactOut via pool.swap with negative amountSpecified
        if (kind == 3) {
            return _quoteAlgebraExactOut(step.pool, step.tokenIn, amountOut);
        }

        // V4: ExactOut via external Uniswap V4 Quoter
        if (kind == 4) {
            return _quoteV4ExactOut(step, amountOut);
        }

        revert UNKNOWN_KIND(kind);
    }

    /// @dev Safe wrapper for ExactOut.
    function _quoteExactOutSafe(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn, bool success) {
        try this._quoteExactOutExternal(step, amountOut) returns (uint256 inp) {
            return (inp, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev External wrapper for ExactOut try/catch.
    function _quoteExactOutExternal(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountOut
    ) external returns (uint256) {
        require(msg.sender == address(this), "SELF_ONLY");
        return _quoteExactOut(step, amountOut);
    }

    // =========================================================
    // Internal — batch helpers
    // =========================================================

    /// @dev Batch from calldata array.
    function _quoteExactInBatchInternal(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    /// @dev Batch from memory array (for store-based calls).
    function _quoteExactInBatchMem(
        SwapStepsConfigStore.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    /// @dev Batch with impact from calldata.
    function _quoteExactInBatchWithImpactCalldata(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteBatchItem[] memory results) {
        uint256 n = steps.length;
        results = new ImpactQuoteBatchItem[](n);
        for (uint256 i = 0; i < n; i++) {
            ImpactQuoteResult memory r = _quoteExactInWithImpact(steps[i], amountIn, referenceAmountIn);
            results[i] = ImpactQuoteBatchItem({
                index: i,
                amountOut: r.amountOut,
                referenceAmountOut: r.referenceAmountOut,
                outPerInX18: r.outPerInX18,
                referenceOutPerInX18: r.referenceOutPerInX18,
                priceImpactPpm: r.priceImpactPpm,
                sellAmountOut: r.sellAmountOut,
                profit: r.profit,
                canTradeAmountIn: r.canTradeAmountIn,
                success: r.success
            });
        }
    }

    /// @dev Batch with impact from memory array (store-based).
    function _quoteExactInBatchWithImpactMem(
        SwapStepsConfigStore.SwapStep[] memory steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteBatchItem[] memory results) {
        uint256 n = steps.length;
        results = new ImpactQuoteBatchItem[](n);
        for (uint256 i = 0; i < n; i++) {
            ImpactQuoteResult memory r = _quoteExactInWithImpact(steps[i], amountIn, referenceAmountIn);
            results[i] = ImpactQuoteBatchItem({
                index: i,
                amountOut: r.amountOut,
                referenceAmountOut: r.referenceAmountOut,
                outPerInX18: r.outPerInX18,
                referenceOutPerInX18: r.referenceOutPerInX18,
                priceImpactPpm: r.priceImpactPpm,
                sellAmountOut: r.sellAmountOut,
                profit: r.profit,
                canTradeAmountIn: r.canTradeAmountIn,
                success: r.success
            });
        }
    }

    // =========================================================
    // Internal — round-trip helpers
    // =========================================================

    /// @dev Round-trip for a single step:
    ///      1) ExactIn:  amountIn tokenIn → buyAmountOut tokenOut
    ///      2) ExactOut:  sellAmountOut tokenOut → amountIn tokenIn  (how much tokenOut needed to buy back amountIn)
    ///      profit = buyAmountOut - sellAmountOut (both in tokenOut)
    ///      If profit > 0 → we got more tokenOut than needed to buy back our tokenIn.
    function _quoteRoundTripInternal(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn,
        uint256 index
    ) internal returns (RoundTripResult memory r) {
        r.index = index;

        // Step 1: ExactIn forward — amountIn tokenIn → buyAmountOut tokenOut
        (uint256 buyOut, bool buyOk) = _quoteExactInSafe(step, amountIn);
        if (!buyOk || buyOut == 0) {
            r.success = false;
            return r;
        }
        r.buyAmountOut = buyOut;

        // Step 2: ExactOut reverse — how much tokenOut to pay to get exactly amountIn tokenIn back
        // We invert the step (tokenOut→tokenIn) and ask: how much tokenOut input for amountIn tokenIn output
        SwapStepsConfigStore.SwapStep memory inv = _invertStep(step);
        (uint256 sellCost, bool sellOk) = _quoteExactOutSafe(inv, amountIn);
        if (!sellOk) {
            r.success = false;
            return r;
        }

        r.sellAmountOut = sellCost;
        r.profit = int256(buyOut) - int256(sellCost);
        r.success = true;
    }

    /// @dev Batch round-trip from calldata.
    function _quoteRoundTripBatchCalldata(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

    /// @dev Batch round-trip from memory (store-based).
    function _quoteRoundTripBatchMem(
        SwapStepsConfigStore.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

    // =========================================================
    // Internal — step inversion
    // =========================================================

    /// @dev Invert a step: swap tokenIn↔tokenOut, reverse path. Pool stays the same (V3/Algebra).
    function _invertStep(
        SwapStepsConfigStore.SwapStep memory s
    ) internal pure returns (SwapStepsConfigStore.SwapStep memory inv) {
        inv.kind    = s.kind;
        inv.router  = s.router;
        inv.pool    = s.pool;
        inv.tokenIn = s.tokenOut;   // reversed
        inv.tokenOut = s.tokenIn;   // reversed

        // Reverse path for V2 (length 2)
        if (s.path.length == 2) {
            address[] memory revPath = new address[](2);
            revPath[0] = s.path[1];
            revPath[1] = s.path[0];
            inv.path = revPath;
        } else {
            inv.path = new address[](0);
        }
    }
}

